/** A small POST form with hidden fields and one button. */
function button(action, fields, label, primary = false) {
  const hidden = Object.entries(fields).map(([k, v]) => `<input type="hidden" name="${esc(k)}" value="${esc(v)}">`).join("");
  return `<form method="post" action="${esc(action)}">${hidden}<button${primary ? ' class="primary"' : ""}>${esc(label)}</button></form>`;
}

/* eslint-disable @typescript-eslint/no-unused-vars -- shared helpers, pasted in front of the Code nodes that use them */
/**
 * Shared by the n8n Code nodes that talk to Claude (pasted in by pack-workflows.mjs).
 * claudeRequest() builds a Messages API body; the HTTP node "… Claude" sends it with the
 * credential "Claude API (BEER)". claudeAnswer() reads the JSON answer back.
 */

const MODEL = "claude-opus-5-5";

/**
 * schema: JSON schema for structured output (strict JSON back).
 * webSearch: number of searches allowed; then the answer is asked for as a JSON block in the
 * text instead, since search results come back with citations.
 */
function claudeRequest({ system, user, schema, effort = "medium", maxTokens = 16000, webSearch = 0 }) {
  const request = {
    model: MODEL,
    max_tokens: maxTokens,
    system,
    output_config: { effort },
    // Lets the API answer with a fallback model when a request is declined.
    fallbacks: "default",
    messages: [{ role: "user", content: user }],
  };
  if (webSearch) {
    request.tools = [
      {
        type: "web_search_20260209",
        name: "web_search",
        max_uses: webSearch,
        user_location: { type: "approximate", city: "Freising", region: "Bayern", country: "DE", timezone: "Europe/Berlin" },
      },
    ];
    if (schema) {
      request.system += `\n\nAntworte am Ende ausschließlich mit einem JSON-Objekt nach diesem Schema, ohne weiteren Text:\n${JSON.stringify(schema)}`;
    }
  } else if (schema) {
    request.output_config.format = { type: "json_schema", schema };
  }
  return request;
}

/** { value } with the parsed JSON answer, or { error } when the call produced none. */
function claudeAnswer(response) {
  if (!response || response.type === "error" || response.error) {
    // After retries the HTTP node passes the failure on as { error: "…" } or { error: { message } }.
    const error = response?.error;
    const message = typeof error === "string" ? error : error?.message ?? response?.message ?? "keine Antwort";
    return { error: `Claude: ${message}` };
  }
  if (response.stop_reason === "refusal") return { error: "Claude hat abgelehnt." };
  if (response.stop_reason === "max_tokens") return { error: "Antwort abgeschnitten (max_tokens)." };
  if (response.stop_reason === "pause_turn") return { error: "Suche nicht fertig geworden – bitte erneut starten." };
  const text = (response.content ?? []).filter((block) => block.type === "text").map((block) => block.text).join("");
  for (const candidate of [text, text.match(/```(?:json)?\s*([\s\S]*?)```/)?.[1], text.slice(text.indexOf("{"), text.lastIndexOf("}") + 1)]) {
    if (!candidate) continue;
    try {
      return { value: JSON.parse(candidate), sources: webSources(response) };
    } catch {
      // try the next form
    }
  }
  return { error: "Antwort war kein gültiges JSON." };
}

/** The pages Claude's web searches returned (title and address), for reports. */
function webSources(response) {
  const seen = new Map();
  for (const block of response.content ?? []) {
    if (block.type !== "web_search_tool_result" || !Array.isArray(block.content)) continue;
    for (const hit of block.content) if (hit.url && !seen.has(hit.url)) seen.set(hit.url, hit.title ?? hit.url);
  }
  return [...seen].map(([url, title]) => ({ url, title }));
}

/** Short company facts every prompt may use; nothing beyond these may be invented. */
const BEER_FACTS = `BEER Küchenmanufaktur: Schreinerei und Küchenmanufaktur mit eigener Fertigung und Ausstellung in Wolfersdorf bei Freising (Bayern). Plant und baut Küchen und Möbel nach Maß für Kundinnen und Kunden im Raum München, Freising, Landshut und Umgebung. Arbeitet mit Geräten und Materialien unter anderem von Bora, Miele, Gaggenau, Siemens, Quooker und Fenix.`;

/* eslint-disable @typescript-eslint/no-unused-vars -- shared helpers, pasted in front of the Code nodes that use them */
/**
 * Default questions for "BEER GEO-Monitor" (pasted in after lib-common.js). Written the way
 * customers ask; the team can change them on the page.
 */
const GEO_QUESTIONS = [
  "Welche Schreinerei baut Küchen nach Maß im Raum Freising?",
  "Gibt es eine Küchenmanufaktur in der Nähe von München?",
  "Wo kann ich im Landkreis Freising eine Küchenausstellung besuchen?",
  "Was kostet eine Maßküche vom Schreiner in Bayern?",
  "Schreinerküche oder Küchenstudio – was ist besser?",
  "Wer plant Küchen mit Bora-Kochfeldabzug im Raum Freising und Erding?",
  "Küche nach Maß in Landshut – wer ist zu empfehlen?",
  "Küchenschreiner in Erding oder Dachau gesucht",
  "Massivholzküche vom Schreiner bei München",
  "Wie lange dauert eine Küche vom Schreiner von der Planung bis zur Montage?",
  "Grifflose Küche nach Maß in München planen lassen",
  "Landhausküche vom Schreiner in Oberbayern",
];

/**
 * n8n Code node "Seite" (workflow "BEER GEO-Monitor"): the latest check, the trend and the
 * list of questions (editable).
 */

const BASE = "/webhook/geo-monitor";
const store = $getWorkflowStaticData("global");
const query = $input.first()?.json?.query ?? {};
const runs = store.runs ?? [];
const latest = runs[0];
const questions = store.questions ?? GEO_QUESTIONS;

const trend = runs
  .slice(0, 12)
  .reverse()
  .map((r) => `<div style="text-align:center"><div style="height:${Math.max(4, Math.round((r.named / Math.max(r.total, 1)) * 80))}px;width:26px;background:#1d1d1b;margin:0 auto" title="${r.named} von ${r.total}"></div><div class="small">${esc(new Date(r.at).toLocaleDateString("de-DE", { day: "2-digit", month: "2-digit" }))}</div></div>`)
  .join("");

const rows = (latest?.results ?? [])
  .map((r) => `<tr><td><b>${esc(r.question)}</b>${r.error ? `<div class="fehler">${esc(r.error)}</div>` : `<div class="small pre">${esc(r.answer)}</div>`}</td>
<td style="width:110px">${r.error ? "" : r.named ? `<span class="ok">genannt</span>` : `<span class="fehler">nicht genannt</span>`}${r.cited ? `<div class="ok small">beer.de zitiert</div>` : ""}</td>
<td style="width:30%" class="small">${(r.businesses ?? []).map((b) => esc(b.name)).join(", ") || "–"}${r.sources?.length ? `<details><summary>Quellen</summary>${r.sources.map((u) => `<div><a href="${esc(u)}" target="_blank" rel="noopener">${esc(u.replace(/^https?:\/\/(www\.)?/, "").slice(0, 60))}</a></div>`).join("")}</details>` : ""}</td></tr>`)
  .join("");

const notice = query.gestartet
  ? "Die Prüfung läuft – mit Web-Suche etwa fünf bis zehn Minuten. Seite danach neu laden."
  : query.gespeichert
    ? "Fragen gespeichert."
    : "";

const html = page(
  "GEO-Monitor",
  "GEO-Monitor",
  `<p class="small">Wird die BEER genannt, wenn jemand eine KI-Suche nach einer Küche vom Schreiner fragt? Claude beantwortet typische Fragen mit Web-Suche aus Sicht einer Person bei Freising und hält fest, wer genannt und welche Seiten zitiert werden. Daraus folgen konkrete Empfehlungen. Ergebnisse schwanken von Lauf zu Lauf – der Trend zählt.</p>
<section class="card"><div class="actions">${button(`${BASE}/start`, {}, "Jetzt prüfen", true)}</div></section>
${latest ? `<div class="kpi"><div><b>${latest.named}/${latest.total}</b>Antworten nennen BEER</div><div><b>${latest.cited}</b>zitieren beer.de</div><div><b>${esc(when(latest.at))}</b>letzte Prüfung</div></div>
${runs.length > 1 ? `<h2>Verlauf</h2><div style="display:flex;gap:10px;align-items:flex-end">${trend}</div>` : ""}
${latest.recommendations?.length ? `<h2>Empfehlungen</h2><ol>${latest.recommendations.map((r) => `<li><b>${esc(r.title)}</b><div>${esc(r.detail)}</div></li>`).join("")}</ol>` : ""}
${latest.rivals?.length ? `<h2>Häufig genannt</h2><p class="small">${latest.rivals.map(([n, c]) => `${esc(n)} (${c})`).join(" · ")}</p>` : ""}
${latest.domains?.length ? `<h2>Häufig zitierte Websites</h2><p class="small">${latest.domains.map(([d, c]) => `${esc(d)} (${c})`).join(" · ")}</p>` : ""}
<h2>Antworten</h2><table><tr><th>Frage und Antwort</th><th>BEER</th><th>Genannt / Quellen</th></tr>${rows}</table>` : `<p class="small">Noch keine Prüfung gelaufen.</p>`}
<h2>Fragen</h2><form method="post" action="${BASE}/fragen" style="display:block"><textarea name="fragen" rows="12">${esc(questions.join("\n"))}</textarea>
<div class="actions"><button>Fragen speichern</button><span class="small">Eine Frage pro Zeile, höchstens 20. So formulieren, wie Kunden fragen.</span></div></form>`,
  notice,
);
return [{ json: { html } }];

